import { contentFactory } from "../services/contentFactory";
import { createPoll } from "../services/pollService";

const handleSubmit = async (e) => {
  e.preventDefault();

  if (mode === "poll") {
    try {
      await createPoll(
        {
          question: pollQuestion,
          options: pollOptions.filter((o) => o.trim() !== ""),
          channel: selectedChannel,
        },
        token
      );
      alert("✅ Опитування створено!");
      window.location.href = "/";
    } catch (err) {
      alert(err.message);
    }
  } else {
    try {
      const type = selectedChannel ? "channel_article" : "article";
      const createContent = contentFactory(type, token);
      await createContent(articleData);
      alert("✅ Статтю створено!");
      window.location.href = "/";
    } catch (err) {
      alert(err.message);
    }
  }
};
export default CreateArticlePage;
